with d as (select value r from jsonb_array_elements($q$[{"notes":["Make the filling the day before and refrigerate; assemble and bake just before serving.","Works just as well in the slow cooker: combine all filling ingredients, cook on low for 6–8 hours, then proceed from step 4.","Food safety: Slow-cooked meat is safe once it is tender and the centre has reached at least 75°C."],"id":"c2f3f553-eef5-4589-a0b1-9b9803ab461f"},{"notes":["This stew improves the next day when the flavours have had time to meld. Cool quickly and refrigerate for up to 3 days, or freeze for up to 3 months.","If you don't have wine, use an extra 250 ml beef stock instead.","For camp oven: brown the meat and veg in a big Dutch oven, then pop it straight into the coals for 3 to 4 hours.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"ecf9901e-a4f3-450b-b111-b11b86563e95"},{"notes":["Make the carnitas up to 2 days ahead; reheat gently in a low oven or on the stove with a splash of water.","The reserved pork cooking liquid is liquid gold, use it to warm the carnitas or sip as a broth.","No corn tortillas? Flour tortillas work fine, but corn is the real deal.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"id":"5eed98de-b048-4937-b426-8268ac3eb3a0"},{"steps":[{"text":"Heat the olive oil in a large baking dish or shallow ovenproof pan over medium heat. Add the onion and cook gently, stirring, until softened and translucent, about 5 minutes."},{"text":"Add the garlic and cook, stirring, for 1 minute until fragrant."},{"text":"Add the crushed tomatoes, drained beans, oregano, bay leaves, and chilli flakes. Stir well to combine. Season with salt and pepper to taste."},{"text":"Add 120 ml of water to loosen the sauce slightly, the beans should be mostly submerged in tomato liquid."},{"text":"Transfer the dish to a 180°C oven (or continue cooking in the pan if it's heatproof). Bake uncovered for 45–50 minutes, until the sauce has thickened and reduced slightly and the flavours have melded. Stir once halfway through."},{"text":"Taste and adjust seasoning if needed. The beans should be tender and the sauce should coat them richly. Serve warm or at room temperature."}],"id":"10b27b24-d8cd-4256-a963-cdac1e0791e9"},{"notes":["Make the curry paste up to a day ahead and keep it covered in the fridge. Fresh fish is best for this curry, ask your fishmonger what looks good on the day.","Use whatever white fish is fresh and local: snapper, flathead or barramundi all work well.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"id":"9c2b6448-8db9-4e74-a792-5f9fff87ed52"},{"notes":["Make a bigger batch and cool the broth quickly; it freezes well for up to 3 months.","If you can't find good pork bones, use a ham hock or extra corned beef – the broth won't be quite as rich but it'll still be aroha kai.","Fresh watercress is key. If you can't get it, try silverbeet (spinach) or spring greens – add them the same way, just wilted.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"25682751-ac2c-4e12-9c34-87058e392a49"},{"notes":["Yassa is even better the next day. Cool quickly, cover and refrigerate for up to 3 days, or freeze for up to 3 months. Reheat gently on the stove.","Use thighs and drumsticks rather than breast, they stay moist and the skin crisps beautifully in the pan.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"c50877a2-b146-4f2f-9f17-8c91f29ed496"},{"notes":["The dough can be made up to 8 hours ahead and kept covered at room temperature. If it dries out, spritz lightly with water.","The filling can be made several hours ahead and refrigerated. Assemble the dumplings no more than 1 hour before steaming.","If you don't have a bamboo steamer, use a metal steamer rack or even a heatproof plate set on chopsticks above the simmering water, the key is gentle, steady steam.","Food safety: Cook mince and sausages until no pink remains and the centre reaches 75°C."],"steps":[{"text":"Make the dough: mix the hot water into the flour and salt with chopsticks or a fork until a shaggy dough forms. Once cool enough to handle, knead for 8–10 minutes until smooth and elastic. The dough should feel soft and slightly sticky, this high hydration gives you that tender wrapper. Cover and rest for at least 30 minutes."},{"text":"Make the filling: mix the pork, gelatine, spring onion, soy sauce, sesame oil, shaoxing wine, ginger and sugar in a bowl. Stir until just combined, don't overwork it or it will become dense. Taste and adjust seasoning if needed."},{"text":"Divide the dough into 16 equal pieces. Roll each into a ball, then use a small rolling pin or your fingers to flatten into a thin disc about 10 cm across, slightly thicker at the edges than the centre."},{"text":"Place about 1 tbsp of filling in the centre of each wrapper. Bring the edges up and gather at the top, pleating as you go, then twist gently to seal. The dumpling should look like a little purse. Place seam-side up on a small square of baking paper (this stops it sticking to the steamer)."},{"text":"Set up a steamer: bring water to a boil in a wok or large pot, and place a bamboo steamer basket or metal steamer rack above it, making sure the water doesn't touch the base of the basket."},{"text":"Working in batches, carefully place 4–6 dumplings seam-side up in the steamer, still on their paper squares. Steam over simmering water for 10–12 minutes, until the wrappers are translucent and cooked through. You'll see a slight sheen on them when they're ready."},{"text":"Transfer the cooked dumplings to a serving platter. Warm the chicken stock gently with the ginger slices and spring onion if using, then ladle into small bowls or a shallow serving dish. Serve the dumplings alongside, with black vinegar and extra stock for dipping."}],"id":"25ec600a-90c1-4302-a69d-763241774fc1"},{"diets":["vegetarian","vegan","no-gluten","no-dairy"],"notes":["Make the dosa batter 1 to 2 days ahead and keep it in the fridge. It ferments and becomes more flavourful. Use it straight from the fridge, don't bring it to room temperature.","If the batter is too thick, thin it with a splash of water. It should pour easily but still coat the pan.","The potato can be boiled and diced an hour ahead."],"id":"f939bd18-4da9-4a1d-a0d8-9225da53bc26"},{"diets":["no-gluten","no-dairy"],"notes":["This keeps well in the fridge for 2 days and freezes beautifully for up to 3 months. Reheat gently on the stove.","Ayesha's tip: Don't rush the tomato-breaking-down stage. That's where the flavour sits. If you like more heat, add a pinch of dried chilli flakes with the ground spices or more green chilli.","Food safety: Cook chicken (and other poultry) until the thickest part reaches 75°C and the juices run clear, with no pink meat near the bone."],"id":"d6c72295-7eae-4632-b708-b47b82a47ed9"},{"notes":["Use the freshest sashimi-grade tuna available. If you're unsure about the source, ask your fishmonger.","Coconut vinegar adds a more authentic Visayan flavour, but white vinegar works well too.","Eat the same day you make it – the acid cures the fish but doesn't preserve it like cooking does.","The fish here is eaten raw or only cured in citrus. Buy sashimi-grade fish from a fishmonger, keep it cold and eat it the same day; skip it for anyone pregnant, very young, elderly or with low immunity.","Food safety: The seafood here is served raw or cured, so buy sashimi-grade, keep it cold and eat it the day it is made; for anyone who should avoid raw fish, cook it until opaque. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"c43efa04-2bda-428d-b292-05ec9c97683a"},{"diets":["pescatarian","no-gluten","no-dairy"],"notes":["The laksa paste can be made the day before and kept in an airtight container in the fridge.","Use the freshest mackerel you can find, the quality makes all the difference. If fresh mackerel is hard to find, try Spanish mackerel or another firm white fish.","The broth can be made ahead and reheated gently; cook the noodles fresh just before serving.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Soak the dried chillies in hot water for 10 minutes until soft. Drain and roughly chop."},{"text":"Pound the softened chillies, garlic, galangal, ginger, shrimp paste and 2 tbsp tamarind paste together in a mortar until you have a rough paste (or blend in a food processor)."},{"text":"Heat the 2 tbsp oil in a large pot over medium heat. Add the laksa paste and fry, stirring, for about 3 minutes until fragrant and darker in colour."},{"text":"Pour in the fish stock and bring to a gentle simmer. Add the halved mackerel and cook for 8 to 10 minutes until the fish is cooked through, the flesh should flake easily."},{"text":"Stir in the coconut milk and the extra 2 tbsp tamarind paste. Taste and season with salt and palm sugar if you like a bit of sweetness. Simmer for another 2 minutes. The broth should be spicy, sour and rich."},{"text":"While the soup cooks, blanch the fresh rice noodles in a large pot of boiling water for 1 to 2 minutes until just tender. Divide among serving bowls."},{"text":"Carefully remove the mackerel pieces from the soup and divide among the bowls. Ladle the hot broth over the noodles."},{"text":"Top each bowl with cucumber, pineapple, a hard-boiled egg half, fresh herbs and fried shallots. Serve hot."}],"id":"61660d26-a814-4c2d-ac22-cc41b999ffc2"},{"notes":["Make this the day before and reheat gently, the flavour deepens overnight.","Freeze the sauce in portions for up to three months.","Serve over fresh pasta, pappardelle, or rigatoni, with a scatter of fresh basil and parmesan.","Cook pork until it reaches at least 70°C in the thickest part (75°C for mince and sausages).","Food safety: Cook whole cuts of beef, lamb and pork to at least 63°C in the thickest part, then rest for 3 minutes; cook pork and any rolled or stuffed cuts until the juices run clear."],"id":"bf204f98-d8ef-433c-8661-0d1e4dc2b481"},{"notes":["Borscht keeps well in the fridge for up to 4 days, and the flavour deepens each day. Reheat gently on the stove.","For a vegetarian version, skip the beef and use vegetable stock instead; the soup will need only 45 minutes on the stove after the vegetables go in.","Some cooks add 200 g cooked kidney beans with the potatoes for a heartier soup.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"id":"c712f7d0-9d23-4eb0-99d9-82d493fe43b7"},{"notes":["Bredie improves overnight as the spices deepen. Make it the day before and gently reheat it.","If you can't find dried apricots, use dried peaches or a combination of apricots and raisins.","Traditionally made with mutton; lamb shoulder works beautifully and cooks a little faster.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the oil in a large, heavy pot over medium-high heat. Working in batches, brown the lamb on all sides, about 3–4 minutes per batch. Set aside."},{"text":"In the same pot, cook the onions over medium heat, stirring, until soft and golden, about 8 minutes. Add the garlic and cook for 1 minute more."},{"text":"Add the turmeric, cinnamon, coriander and black pepper. Stir through the onions, cooking gently for 1 minute until fragrant."},{"text":"Return the lamb to the pot. Pour in the stock and add the bay leaves. Stir in the golden syrup and apricots. Bring to a simmer, then reduce the heat to low, cover, and cook gently for 1 hour, or until the lamb is very tender."},{"text":"Stir in the lemon juice, taste, and adjust the salt and spices if needed. The stew should be balanced, warm spice, a touch of sweetness from the apricots, and a hint of brightness from the lemon."},{"text":"Serve hot, spooned over plain boiled rice."}],"id":"a7013c30-d19d-4d05-a994-34aa4054b037"},{"notes":["Make the potato mixture just before frying, it will start to weep if left to sit. If you must wait, drain and squeeze it again before cooking.","The crème fraîche topping can be made up to a day ahead and kept refrigerated."],"steps":[{"text":"Squeeze the grated potato and onion firmly in a clean tea towel to remove as much moisture as possible, this is essential for crispy pancakes."},{"text":"In a bowl, whisk the eggs, then stir in the drained potato and onion, flour, salt and pepper until combined."},{"text":"Heat about 5 mm of oil in a large frying pan over medium-high heat. When the oil is shimmering, carefully spoon the mixture into the pan in loose mounds (about 6 cm across) and flatten them gently with the back of a spatula."},{"text":"Fry for 4 to 5 minutes until the underside is golden and crisp. Flip and cook the other side for another 3 to 4 minutes until golden. Work in batches and keep cooked pancakes warm on a plate lined with paper towel."},{"text":"While the pancakes cook, fold the dill into the crème fraîche and season lightly with salt and pepper."},{"text":"Serve the warm pancakes topped with a spoonful of dill crème fraîche and a few pieces of smoked salmon. Finish with a squeeze of lemon if you like."}],"id":"dacfb7da-4ddc-4f12-9a2f-2c50ad93cb31"},{"notes":["This adobo tastes even better the next day, anak. Keep it in the fridge and warm it gently before serving.","If you don't have calamansi, use fresh lime juice or good white vinegar, both work beautifully.","Corazon always serves this with plain steamed white rice and a simple green vegetable.","Food safety: Cook chicken and other poultry until the juices run clear and the thickest part reaches 75°C."],"steps":[{"text":"Heat the oil in a large heavy pot or deep pan over medium-high heat. Working in batches, brown the chicken pieces all over, about 5 minutes per batch. Set aside."},{"text":"In the same pot, add the crushed garlic and peppercorns. Stir constantly for about 1 minute until fragrant."},{"text":"Pour in the vinegar and soy sauce, stirring well to combine. Return the chicken to the pot and add the bay leaves and water. Bring to a simmer until the liquid is gently bubbling."},{"text":"Reduce heat to low, cover, and braise gently for 40–45 minutes, turning the chicken halfway through, until the chicken is very tender and cooked through (the juices should run clear when pierced)."},{"text":"Taste and adjust salt as needed. The sauce should be rich and deeply flavoured."},{"text":"Serve hot with steamed rice, anak."}],"id":"3a1ea6f4-9ee6-42c5-bcf5-d87e47b9415c"},{"steps":[{"text":"Score the flesh of each eggplant half with shallow cuts in a crosshatch pattern, being careful not to pierce the skin."},{"text":"Brush the eggplant flesh generously with oil. Season lightly with salt."},{"text":"Heat a grill pan or barbecue to medium-high. Grill the eggplants flesh-side down for 6 to 8 minutes, until soft and charred. Turn skin-side down and grill for another 1 to 2 minutes."},{"text":"While the eggplants cook, whisk together the miso, sugar, mirin, and dashi powder in a small bowl until smooth."},{"text":"Transfer the grilled eggplants to a serving plate, flesh-side up. Spread the miso glaze generously over the hot flesh, it will warm and soften."},{"text":"Scatter sesame seeds over the top and serve at once."}],"id":"9b646868-ca00-479b-9e83-147f5c225fff"},{"notes":["Cold, leftover rice works best, warm rice gets mushy. Spread it on a tray and refrigerate for at least 2 hours.","The key to those crispy golden bits (cơm cháy) is letting the rice sit untouched on the hot pan for 30 seconds at a time before stirring.","For extra flavour, add a splash of soy sauce or a drizzle of chilli oil after cooking.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"id":"13100f29-7e29-44e3-b2b3-f2b7d0cb923d"},{"notes":["Nduja keeps well in the fridge for weeks once opened. Wrap it tightly or keep it in an airtight container.","If you can't find nduja at your local deli, check the Italian section at a good supermarket or order it online, it's worth the hunt."],"steps":[{"text":"Bring a large pot of salted water to the boil and cook the spaghetti until just al dente, about 9–10 minutes. Reserve 200 ml of pasta water, then drain."},{"text":"While the pasta cooks, place the nduja and garlic in a large frying pan over medium-low heat. Stir gently for 2–3 minutes until the nduja starts to break down and release its oils, don't let it brown."},{"text":"Add the crushed tomatoes to the pan and stir well to combine with the nduja and garlic. Simmer for 4–5 minutes until the sauce thickens slightly."},{"text":"Pour in the cream and stir through. Season with salt and black pepper to taste. Add a splash of pasta water if the sauce is too thick, it should coat the pasta loosely."},{"text":"Add the cooked spaghetti to the pan and toss gently to coat every strand. Add a little more pasta water if needed to loosen the sauce."},{"text":"Divide among four bowls and finish with a generous handful of grated parmesan and a basil leaf, if you like."}],"id":"fd25a6df-83e0-479a-a9ce-a6bb1a8e326b"},{"notes":["Make a big batch of sambal matah and keep it in the fridge for up to three days, it's brilliant on rice, eggs, or any leftover protein.","If you can't find fresh lime, use lemon or bottled lime juice, but fresh is so much better.","Tempeh keeps in the fridge for ages; fry it whenever you need a quick, protein-packed lunch."],"steps":[{"text":"Make the sambal matah first: combine the shallots, chillies and garlic in a bowl. Add the lime juice and neutral oil, then taste and add salt. Set aside while you fry the tempeh."},{"text":"Heat about 1 cm of neutral oil in a frying pan over medium-high heat until it shimmers. Test with a piece of tempeh, it should sizzle immediately."},{"text":"Working in batches so you don't crowd the pan, fry the tempeh slices until golden and crispy on both sides, about 3–4 minutes total. Drain on paper towel and sprinkle with salt while still hot."},{"text":"Arrange the hot fried tempeh on a plate and spoon the sambal matah over the top. Eat straight away, the contrast between the crispy, hot tempeh and the cool, bright sambal is the whole point."}],"id":"28ef8146-ab36-402b-91ee-fadd0dca65c9"},{"notes":["The key is drying the tofu well before frying, squeeze it gently between clean cloths to release as much water as you can.","Atsuage is best eaten straight away, while the outside is still crackling and the inside soft."],"steps":[{"text":"Pat the tofu slices dry with paper towels. Blot both sides well, this is important for crispy frying."},{"text":"Heat about 3 cm of oil in a small, deep pan to 160°C. The tofu will sink and then float as it cooks; if you don't have a thermometer, test with a wooden chopstick, bubbles should form steadily around it."},{"text":"Carefully lower the tofu into the hot oil. Fry for 4 minutes until the surface is golden and crispy, then gently turn it over and fry for another 4 minutes until both sides are golden."},{"text":"Warm the dashi in a small saucepan. Stir in the soy sauce and mirin."},{"text":"Transfer the hot tofu to a bowl. Pour the hot dashi over it. Top with the grated daikon and spring onion. Eat while it's still steaming."}],"id":"c023802c-efe9-4a60-8272-855837786cac"},{"notes":["Salt cod must be soaked for 24 hours before cooking. Start the night before.","Choricero peppers are essential, they give the sauce its deep colour and flavour. Find them in Spanish delis or good supermarkets; regular dried peppers work but won't taste the same.","This dish is best made in a heavy earthenware cazuela, but any heavy-bottomed pan works fine."],"steps":[{"text":"Soak the salt cod in cold water for 24 hours, changing the water every 6–8 hours. This draws out the salt. After soaking, drain and place in a large pot with 1 litre of fresh cold water. Bring slowly to a gentle simmer, do not boil. Simmer for 8–10 minutes until the flesh is tender and flakes easily. Remove from heat, drain gently, and set aside on a warm plate. Keep the cooking broth."},{"text":"While the cod simmers, prepare the sauce. Toast the dried choricero peppers briefly in a dry pan over medium heat, about 30 seconds each side, until fragrant. Soak them in 200 ml of warm water for 10 minutes to soften, then drain. Scrape the flesh from the skin with a spoon and discard the skins and seeds. You should have a dark red paste."},{"text":"Heat the olive oil in a heavy pan over medium heat. Add the chopped onion and cook gently, stirring occasionally, for about 8 minutes until soft and golden. Add the sliced garlic and cook for 1 minute more until fragrant."},{"text":"Stir in the paprika and cook for 30 seconds. Add the pepper paste you made, the tinned tomatoes, and 2 tablespoons of water. Stir well to combine. Simmer gently for 15 minutes, stirring often, until the sauce darkens and thickens slightly. Season with salt and black pepper to taste."},{"text":"Carefully place the warm salt cod fillets into the sauce. Pour about 100 ml of the reserved cooking broth around (not over) the cod. Simmer very gently for 5 minutes, the cod will break apart if you're rough with it. The sauce should be rich, dark, and coat the fish."},{"text":"Serve in deep earthenware bowls with the sauce spooned around the fish. Eat with good bread and a glass of txakoli or dry white wine."}],"id":"ffcbde4c-6199-40c3-998c-77331d4685d5"},{"diets":["pescatarian"],"notes":["Make the quenelle mixture up to 2 hours ahead and chill. The sauce can be made while the quenelles poach.","If pike isn't available, perch, barramundi or any firm white fish works well, this is a weeknight dinner, not a pilgrimage.","Food safety: Cook fish until it is opaque and flakes easily (63°C in the thickest part), and prawns until pink and opaque all the way through."],"steps":[{"text":"Pulse the fish fillet in a food processor until very finely minced. Add the softened butter and pulse until you have a pale, creamy paste. Work in the eggs one at a time, then fold in the cream by hand. Season with salt, white pepper and nutmeg. Taste a tiny spoonful by poaching it briefly in a small pan of water to check the seasoning. Chill for 10 minutes."},{"text":"Bring the stock to a gentle simmer in a large, wide pan. Using two warm wet spoons, shape the pike mixture into quenelle shapes (or simply oval dumplings, don't fuss). Gently slide them into the simmering stock. They'll sink, then float to the surface when cooked through, about 4 minutes. Poach in two batches if needed so they're not crowded. Lift them out with a slotted spoon and keep warm on a plate."},{"text":"For the sauce: melt the butter in a small pan over medium heat. Whisk in the flour to make a smooth roux and cook, stirring, for 2 minutes. Gradually whisk in the stock, then the cream, stirring until smooth. Simmer for 3 minutes. Stir in the cooked prawn and sherry, season with salt, white pepper and a pinch of cayenne. Taste and adjust."},{"text":"Arrange the quenelles in a warmed shallow dish or on individual plates. Pour the Nantua sauce over and serve at once."}],"id":"0d179c07-2625-4181-adf1-641f44950667"},{"notes":["Leftovers keep in the fridge for 3 days. Reheat gently on the stove, adding a splash of water if it's thickened too much.","Use rotisserie chicken, or shredded leftover roast chicken. If you don't have cooked chicken, add 300 g raw chicken breast to the pot with the stock and cook for 12 minutes before adding lentils.","Swap red lentils for brown lentils if you prefer a firmer texture; they'll need the full 25 minutes to cook.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear."],"id":"2686f275-a762-49c4-b6a2-798d2dd5cd17"},{"notes":["Make the sauce while the pork cooks: mix mirin, soy sauce and water in a small bowl and you're ready to go.","No fresh pork cutlets? Thin chicken breast works just as well, pound it to 5 mm and it'll cook in the same time.","Leftover rice from lunch? This dish is your friend. Just make sure it's still warm when you serve.","Food safety: Cook fresh pork to at least 70°C in the thickest part. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system. Cool any leftover rice quickly and refrigerate it within an hour; reheat it until steaming hot."],"steps":[{"text":"Set up your crumbing station: put the flour in one shallow bowl, beaten egg in another, and panko in a third. Season the pork with salt and pepper, then coat in flour, shaking off excess. Dip in beaten egg, then press into panko until fully coated."},{"text":"Heat 3 tbsp oil in a large frying pan over medium-high heat. When it's hot and shimmering, carefully lay the pork cutlets in and cook until golden and crisp, 3 to 4 minutes on each side. The pork is done when it reaches 63°C in the thickest part. Transfer to a plate."},{"text":"In the same pan, reduce heat to medium and add the sliced onion. Cook, stirring, until soft and golden, about 4 minutes. Add the mirin, soy sauce and water, and bring to a simmer."},{"text":"Slice each pork cutlet into strips. Return the pork to the pan, nestled among the onions, and simmer for 2 minutes to warm through and coat with sauce."},{"text":"Push the pork and onions to the sides of the pan. Pour the beaten eggs into the sauce, and without stirring, let them cook for 1 to 2 minutes until just set but still slightly glossy on top, you want the eggs to stay soft."},{"text":"Divide the warm rice between two bowls. Carefully slide the pork, onions and egg over the rice, spoon the sauce over top, and scatter spring onions and nori strips if using. Serve immediately."}],"id":"795570fd-0229-4591-a731-1b8a867fb2ad"},{"notes":["Make the braised pork up to 2 days ahead. It keeps in the fridge in its sauce and tastes even better reheated.","The eggs are best cooked just before serving, but you can boil them ahead and reheat gently in hot water.","Food safety: Cook fresh pork to at least 70°C in the thickest part. Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"id":"2d1bc7d0-5a83-4658-9281-fc64086ba898"},{"notes":["The filling must cool completely before adding the pastry, or it'll go soggy. Make it the day before if you like.","You can freeze the uncooked pie for up to a month. Bake straight from frozen, adding 10–15 minutes to the cooking time.","Swaps: button mushrooms work fine if you can't get swiss browns, or use a mix. Crème fraîche instead of cream if that's what you've got.","Cook chicken until it reaches 75°C in the thickest part and the juices run clear.","Food safety: Raw and lightly cooked foods aren't recommended for pregnant women, young children, older people or anyone with a weakened immune system."],"steps":[{"text":"Make the pastry: rub the butter into the flour and salt until it looks like breadcrumbs. Mix the egg yolk with cold water, pour it in, and bring it together into a dough with your hands. Wrap in cling film and chill while you make the filling."},{"text":"Melt the butter in a large heavy-bottomed pan over medium-high heat. Season the chicken with salt and pepper, then brown it in batches, about 3 minutes each side, don't crowd the pan. Set aside."},{"text":"In the same pan, add the onion and cook until soft, about 5 minutes. Add the garlic and mushrooms, stir, and cook until the mushrooms release their liquid and it evaporates, about 8 minutes."},{"text":"Sprinkle the flour over the veg, stir well, and cook for 1 minute. Pour in the stock and cream, add the mustard, and stir to combine. Return the chicken to the pan, bring to a simmer, and cook gently for 10 minutes. Taste and adjust the seasoning. Let it cool completely, this is important or the pastry will be soggy."},{"text":"Preheat the oven to 200°C. Pour the cooled filling into a 1.5 litre pie dish. Roll out the pastry on a floured bench to about 5 mm thick and about 2 cm larger than the dish. Lay it over the filling, press the edges down, and trim with a knife. Brush with beaten egg."},{"text":"Bake for 25–30 minutes until the pastry is golden brown and the filling bubbles at the edges. Rest for 5 minutes before serving."}],"id":"5da9a85e-7457-4f20-904a-7d29bbb990da"},{"notes":["Use well-aged kimchi for the deepest flavour; old kimchi that's been fermenting for months is better than fresh.","Don't skip the skimming step, it keeps the braise clean and clear.","Leftover kimchi-jjim reheats gently on the stove with a splash of water.","Food safety: Cook fresh pork to at least 70°C in the thickest part."],"id":"ab6e2520-83b7-4243-a9da-a272f9c6604e"},{"notes":["Make it the day before and reheat gently, the flavours deepen. Store in an airtight container in the fridge for up to 4 days.","Serve with couscous or warm flatbread to soak up the sauce.","If you can't find saffron, add a pinch of turmeric instead for warmth and colour.","Food safety: Braised beef and lamb cook well past 75°C on the way to tender, so they are safe once soft."],"steps":[{"text":"Heat the olive oil in a large heavy pot or tagine over medium-high heat. Season the lamb pieces with salt and pepper, then brown them in batches, 3–4 minutes per side. Set aside."},{"text":"In the same pot, cook the onion until soft, about 5 minutes. Add the chopped fresh garlic and fresh ginger, and stir for 1 minute until fragrant."},{"text":"Add the ground ginger, cinnamon, and cumin, stirring constantly for 30 seconds until fragrant, to toast the spices."},{"text":"Return the lamb to the pot and stir well to coat. Pour in the chicken stock and bring to a simmer. Cover and cook gently on low heat for 60 minutes, stirring occasionally."},{"text":"Add the saffron threads and prunes, and stir. Simmer, covered, for another 20–30 minutes until the lamb is very tender and the sauce has thickened slightly."},{"text":"Taste and adjust seasoning with salt and pepper. Serve hot, scattered with fresh coriander if you like."}],"id":"da9abee3-43d7-41c8-a720-1950bff66040"}]$q$::jsonb)), up as (update public.published_recipes p set recipe = p.recipe || (d.r - 'id' - 'notes') || case when d.r ? 'notes' then jsonb_build_object('notes', coalesce((select jsonb_agg(n) from jsonb_array_elements(d.r->'notes') n where btrim(n#>>'{}') <> 'Food safety:'),'[]'::jsonb)) else '{}'::jsonb end, diets = case when d.r ? 'diets' then array(select jsonb_array_elements_text(d.r->'diets')) else p.diets end from d where p.id=(d.r->>'id')::uuid returning p.id) select (select count(*) from d) expected, (select count(*) from up) updated;